mapper.sql:
WHERE 1=1
AND pay_type_cd = #{payTypeCd}
AND pay_dt >= #{fromDt}
AND pay_dt <= #{toDt}

   AND (LOWER(counterpart_nm) LIKE LOWER('%' || #{keyword} || '%')
        OR LOWER(memo) LIKE LOWER('%' || #{keyword} || '%')
        OR LOWER(bank_account) LIKE LOWER('%' || #{keyword} || '%'))

mapper.select:
SELECT * FROM gw_payment

 ORDER BY pay_dt DESC, payment_id DESC
 LIMIT #{limit} OFFSET #{offset}
